const ut8 *parse_dwarf_comp_unit(Sdb *s, const ut8 *obuf, RBinDwarfCompUnit *cu, const RBinDwarfDebugAbbrev *da, size_t offset, const ut8 *debug_str, size_t debug_str_len) {
    if (!s || !obuf || !cu || !da || !debug_str) {
        return NULL;
    }

    const ut8 *cursor = obuf;

    // Read the length of the compilation unit header
    size_t length = read_uleb128(&cursor);
    if (!length) {
        return NULL;
    }

    // Parse the header and determine the version and abbrev offset
    cu->version = *(cursor++);
    if (cursor + length > obuf + 16) {
        return NULL; // Prevent buffer overread
    }

    cu->abbrev_offset = read_uleb128(&cursor);
    cu->abbrev_offset += offset;
    cu->address_size = *(cursor++);

    // Parse the abbreviation definitions
    const RBinDwarfAbbrev *abbrev = r_bin_dwarf_find_abbrev (da, cu->abbrev_offset);
    if (!abbrev) {
        return NULL;
    }

    // Process each DIE
    while (cursor < obuf + length) {
        ut64 abbrev_code = read_uleb128(&cursor);
        if (!abbrev_code) {
            break;
        }

        const RBinDwarfAbbrevEntry *entry = r_bin_dwarf_find_abbrev_entry (abbrev, abbrev_code);
        if (!entry) {
            return NULL;
        }

        RBinDwarfDie *die = sdb_new0();
        die->abbrev = entry;

        // Parse each attribute in the DIE
        for (int i = 0; i < entry->nattrs; i++) {
            const RBinDwarfAttr *attr = &entry->attrs[i];
            ut64 value = read_uleb128(&cursor);
            switch (attr->form) {
                case 0x01: // DW_FORM_addr
                    die->attr[attr->name] = value;
                    break;
                case 0x03: // DW_FORM_block1
                    die->attr[attr->name] = value;
                    break;
                case 0x08: // DW_FORM_string
                    if (value < debug_str_len) {
                        char *str = (char *) &debug_str[value];
                        sdb_set (s, str, "1", 0);
                    }
                    break;
                default:
                    die->attr[attr->name] = value;
                    break;
            }
        }

        // Add die to cu
        r_list_append (cu->dies, die);
    }

    return cursor;
}

const ut8 *parse_dwarf_compilation_unit(Sdb *s, const ut8 *obuf, RBinDwarfCompUnit *cu, const RBinDwarfDebugAbbrev *da, size_t offset, const ut8 *debug_str, size_t debug_str_len) {
	if (!s || !obuf || !cu || !da || !debug_str) {
		return NULL;
	}

	// Implementation of the parsing logic for a DWARF compilation unit
	const ut8 *cursor = obuf;
	if (cursor >= obuf + 8) {
		return NULL; // Avoid out-of-bounds access
	}

	// Parse and initialize compilation unit header
	cu->length = *(const ut32 *)cursor;
	cursor += 4;

	cu->version = *(const ut16 *)cursor;
	cursor += 2;

	cu->abbrev_offset = *(const ut32 *)cursor;
	cursor += 4;

	cu->address_size = *cursor++;
	cu->data = NULL;

	// Initialize DIEs
	RBinDwarfDie *die = r_bin_dwarf_new_die ();
	if (!die) {
		return NULL;
	}
	die->abbrev = da;
	die->offset = cu->abbrev_offset + offset;

	if (die->abbrev->abbrev) {
		// Parse attributes based on abbreviations
		RBinDwarfAbbrev *ab = die->abbrev->abbrev;
		while (ab->tag) {
			const ut8 *attr_value = NULL;
			size_t attr_len = 0;
			switch (ab->form) {
			case DW_FORM_string:
				attr_value = cursor;
				attr_len = strlen ((const char *)cursor);
				cursor += attr_len + 1;
				break;
			case DW_FORM_data4:
				attr_value = cursor;
				cursor += 4;
				break;
			default:
				// Unsupported form, skip
				cursor += 4;
				break;
			}
			if (attr_value) {
				char key[256];
				snprintf (key, sizeof (key), "tag.%d.attr.%d", ab->tag, ab->attr);
				sdb_set (s, key, (const char *)attr_value, 0);
			}
			ab++;
		}
	}

	// Handle compilation directory and store it in the database
	if (cursor < obuf + 8 + cu->length) {
		const char *dir = (const char *)cursor;
		sdb_set (s, "compilation.directory", dir, 0);
		cursor += strlen (dir) + 1;
	}

	return cursor;
}

const ut8 *parse_dwarf_comp_unit(Sdb *s, const ut8 *obuf, RBinDwarfCompUnit *cu, const RBinDwarfDebugAbbrev *da, size_t offset, const ut8 *debug_str, size_t debug_str_len) {
    if (!s || !obuf || !cu || !da || !debug_str) {
        return NULL;
    }

    size_t initial_offset = (size_t)(obuf - (const ut8 *)NULL);
    cu->offset = initial_offset;

    // Validate that the buffer is at least 11 bytes long (minimum for a compilation unit header)
    if (obuf + 11 > (const ut8 *)NULL + debug_str_len) {
        return NULL;
    }

    // Read version
    int version = *(obuf)++;
    version |= (*(obuf)++) << 8;
    cu->version = version;

    // Read unit length
    size_t length = 0;
    for (int i = 0; i < 4; i++) {
        length |= ((size_t)*(obuf)++) << (i * 8);
    }
    cu->length = length;

    // Check for 64-bit extended length
    if (length == 0xFFFFFFFF) {
        if (obuf + 8 > (const ut8 *)NULL + debug_str_len) {
            return NULL;
        }
        cu->length = 0;
        for (int i = 0; i < 8; i++) {
            cu->length |= ((size_t)*(obuf)++) << (i * 8);
        }
        cu->is_64bit = true;
    } else {
        cu->is_64bit = false;
    }

    // Read offset and adjust with the provided offset
    cu->start_offset = initial_offset;
    cu->end_offset = initial_offset + cu->length;

    // Parse abbreviations and attributes
    while (obuf < (const ut8 *)NULL + debug_str_len) {
        // Check for out of bounds
        if (obuf > (const ut8 *)NULL + debug_str_len) {
            return NULL;
        }

        // Read abbreviation code
        size_t abbrev_code = 0;
        for (int i = 0; i < 4; i++) {
            abbrev_code |= ((size_t)*(obuf)++) << (i * 8);
            if (*((const ut8 *)NULL + (size_t)obuf - 1) == 0) {
                break;
            }
        }

        if (abbrev_code == 0) {
            break;
        }

        // Adjust abbreviation code with the provided offset
        abbrev_code += offset;

        const RBinDwarfAbbrev *abbrev = NULL;
        for (int i = 0; i < da->count; i++) {
            if (da->abbrevs[i].code == abbrev_code) {
                abbrev = &da->abbrevs[i];
                break;
            }
        }

        if (!abbrev) {
            return NULL;
        }

        // Initialize the DIE based on the abbreviation
        RBinDwarfDie die;
        die.tag = abbrev->tag;

        // Parse attributes
        for (int j = 0; j < abbrev->num_attributes; j++) {
            const RBinDwarfAttr *attr = &abbrev->attributes[j];
            switch (attr->form) {
                case 0x01: // DW_FORM_addr
                    // Handle address form
                    break;
                case 0x03: // DW_FORM_block1
                    // Handle block1 form
                    break;
                case 0x08: // DW_FORM_string
                    // Handle string form
                    die.name = (char *)obuf;
                    obuf += strlen((const char *)obuf) + 1;
                    break;
                default:
                    // Skip unsupported forms
                    obuf += attr->length;
                    break;
            }

            // Store the DIE in the database if it has a name
            if (die.name) {
                sdb_num_set(s, die.name, 1, 0);
            }
        }

        // Add the DIE to the compilation unit
        // cu->add_die(cu, &die);
    }

    if (obuf >= (const ut8 *)NULL + debug_str_len || obuf > (const ut8 *)NULL + debug_str_len) {
        return NULL;
    }

    return obuf;
}

const ut8 *parse_dwarf_comp_unit(Sdb *s, const ut8 *obuf, RBinDwarfCompUnit *cu, const RBinDwarfDebugAbbrev *da, size_t offset, const ut8 *debug_str, size_t debug_str_len) {
    if (!s || !obuf || !cu || !da || !debug_str) {
        return NULL;
    }

    size_t initial_offset = (size_t)(obuf);
    ut64 length = read_uleb128(&obuf);
    if (length == 0) {
        return NULL;
    }

    cu->length = length;
    cu->version = (int)read_uleb128(&obuf);
    cu->debug_abbrev_offset = (ut64)read_uleb128(&obuf);
    cu->address_size = (int)read_uleb128(&obuf);

    ut64 abbr_offset = cu->debug_abbrev_offset + offset;
    if (abbr_offset >= da->len) {
        return NULL;
    }

    RBinDwarfAbbrev *abbrev = &(da->abbrevs[abbr_offset]);
    while (abbrev->tag != 0) {
        ut64 die_abbr_code = read_uleb128(&obuf);
        if (die_abbr_code == 0) {
            break;
        }

        RBinDwarfDIE die;
        die.tag = abbrev->tag;
        die.abbrev = abbrev;

        const ut8 *end_of_unit = obuf + (cu->length - (obuf - (const ut8 *)initial_offset));
        const ut8 *attr_data = obuf;
        while (obuf < end_of_unit) {
            ut64 attr_name = read_uleb128(&obuf);
            ut64 attr_form = read_uleb128(&obuf);
            if (attr_name == 0) {
                break;
            }

            RBinDwarfAttribute attr;
            attr.name = attr_name;
            attr.form = attr_form;

            switch (attr_form) {
                case 0x01: // DW_FORM_ADDR
                    attr.value.addr = *(ut64 *)obuf;
                    obuf += cu->address_size;
                    break;
                case 0x0b: // DW_FORM_strp
                    attr.value.string = (char *)(debug_str + *(ut32 *)obuf);
                    obuf += sizeof(ut32);
                    break;
                case 0x1c: // DW_FORM_line_strp
                    attr.value.string = (char *)(debug_str + *(ut64 *)obuf);
                    obuf += sizeof(ut64);
                    break;
                default:
                    // Skip unknown forms
                    obuf += calculate_form_size(attr_form, cu->address_size);
                    break;
            }

            // Store attribute in sdb
            char key[256];
            snprintf(key, sizeof(key), "%s/%d/%d", abbrev->name, (int)attr_name, (int)attr_form);
            sdb_num_set(s, key, attr.value.addr, 0);
        }

        // Add die to cu
        cu->dies = realloc(cu->dies, (cu->dies_count + 1) * sizeof(RBinDwarfDIE));
        cu->dies[cu->dies_count++] = die;
        abbrev++;
    }

    return obuf;
}

const ut8 *parse_dwarf_comp_unit(Sdb *s, const ut8 *obuf, RBinDwarfCompUnit *cu, const RBinDwarfDebugAbbrev *da, size_t offset, const ut8 *debug_str, size_t debug_str_len) {
	if (!s || !obuf || !cu || !da || !debug_str) {
		return NULL;
	}

	// Placeholder for parsing the compilation unit from the buffer
	cu->offset = offset;
	cu->debug_str = debug_str;
	cu->debug_str_len = debug_str_len;

	// Initialize the compilation unit fields
	if (!rbindwarf_comp_unit_init (cu, obuf, debug_str, debug_str_len)) {
		return NULL;
	}

	// Iterate through abbreviation entries and populate the compilation unit
	if (!rbindwarf_abbrev_foreach (da, offset, cu)) {
		return NULL;
	}

	// Update the buffer pointer to the next position
	return obuf;
}
